package com.bananalab.lite;
import android.content.*;import java.util.*;import java.util.regex.*;import org.json.*;
/** Own local trainable response retriever. User evidence only; never self-labels generated text. */
final class AdaptiveMemory{
 static final int D=128,MAX=32;static final String[] NEG={"hola","que hora es","crea una banana","publica el borrador","como esta el clima","calcula cinco mas dos","donde esta la luna","como edito un metodo java"};
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-adaptive-memory",0);}
 static Set<String> terms(String question){String q=ChatLanguage.normalize(question);Set<String> stop=new HashSet<>(Arrays.asList("que","como","cual","el","la","los","las","un","una","es","son","de","del","a","en","mi","me","se","por","para","y","con","puedo","podes","decime"));Set<String> out=new TreeSet<>();for(String word:q.split(" "))if(word.length()>1&&!stop.contains(word)){if(word.length()>5&&word.endsWith("s"))word=word.substring(0,word.length()-1);out.add(word);}return out;}
 static float[] vector(String text){float[] v=new float[D];for(String word:terms(text)){int hash=word.hashCode();v[(hash&0x7fffffff)%(D-1)]+=1;for(int i=0;i+3<=word.length();i++)v[(word.substring(i,i+3).hashCode()&0x7fffffff)%(D-1)]+=.15f;}float length=0;for(float x:v)length+=x*x;if(length>0){length=(float)Math.sqrt(length);for(int i=0;i<D-1;i++)v[i]/=length;}v[D-1]=.1f;return v;}
 static float overlap(String a,String b){String na=ChatLanguage.normalize(a),nb=ChatLanguage.normalize(b);if(na.matches("(?s).*\\bno\\b.*")!=nb.matches("(?s).*\\bno\\b.*")||!na.replaceAll("[^0-9]+", " ").trim().equals(nb.replaceAll("[^0-9]+", " ").trim()))return 0;Set<String> x=terms(a),y=terms(b);if(x.isEmpty()||y.isEmpty())return 0;int common=0;for(String word:x)if(y.contains(word))common++;return common/(float)(x.size()+y.size()-common);}
 static final class Model{JSONArray rows;float[][] weights;int exact,heldout,heldoutTotal;Model(JSONArray rows)throws Exception{if(rows.length()>MAX)throw new IllegalArgumentException("Hasta32 respuestas aprendidas.");this.rows=new JSONArray(rows.toString());weights=new float[rows.length()][D];Set<String> known=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);RuntimeProgram.keys(row,"question","answer","variants","source");String q=row.getString("question"),a=row.getString("answer");if(q.length()<4||q.length()>160||a.trim().isEmpty()||a.length()>600||!known.add(ChatLanguage.normalize(q))||row.getJSONArray("variants").length()>4||!row.getString("source").equals("user"))throw new IllegalArgumentException("Ejemplo de aprendizaje inválido.");for(int j=0;j<row.getJSONArray("variants").length();j++){String variant=row.getJSONArray("variants").getString(j);if(variant.length()<4||variant.length()>160||!known.add(ChatLanguage.normalize(variant)))throw new IllegalArgumentException("Variante inválida.");}}}
  float score(int label,float[] v){float sum=0;for(int d=0;d<D;d++)sum+=weights[label][d]*v[d];return sum;}
  void train(boolean holdout)throws Exception{List<String> questions=new ArrayList<>();List<Integer> labels=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);questions.add(row.getString("question"));labels.add(i);JSONArray variants=row.getJSONArray("variants");for(int j=0;j<variants.length()-(holdout&&variants.length()>0?1:0);j++){questions.add(variants.getString(j));labels.add(i);}}
   for(String n:NEG){boolean positive=false;for(String q:questions)if(ChatLanguage.normalize(n).equals(ChatLanguage.normalize(q)))positive=true;if(!positive){questions.add(n);labels.add(-1);}}for(int epoch=0;epoch<24;epoch++)for(int n=0;n<questions.size();n++){float[] v=vector(questions.get(n));for(int label=0;label<rows.length();label++){float s=Math.max(-12,Math.min(12,score(label,v)));float prediction=(float)(1/(1+Math.exp(-s))),error=(labels.get(n)==label?1:0)-prediction;for(int d=0;d<D;d++)weights[label][d]+=.12f*error*v[d];}}}
  int select(String query,boolean exactAllowed)throws Exception{String q=ChatLanguage.normalize(query);if(exactAllowed)for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(q.equals(ChatLanguage.normalize(row.getString("question"))))return i;JSONArray variants=row.getJSONArray("variants");for(int j=0;j<variants.length();j++)if(q.equals(ChatLanguage.normalize(variants.getString(j))))return i;}
   int best=-1;float first=-100,second=-100;float[] v=vector(query);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);float similarity=overlap(query,row.getString("question"));JSONArray variants=row.getJSONArray("variants");for(int j=0;j<variants.length();j++)similarity=Math.max(similarity,overlap(query,variants.getString(j)));if(similarity<.65f)continue;float score=score(i,v)+similarity*2;if(score>first){second=first;first=score;best=i;}else second=Math.max(second,score);}return best>=0&&first-second>.15f?best:-1;}
  JSONObject json()throws Exception{JSONArray matrix=new JSONArray();for(float[] w:weights){JSONArray line=new JSONArray();for(float value:w)line.put(value);matrix.put(line);}return new JSONObject().put("rows",rows).put("weights",matrix).put("exact",exact).put("heldout",heldout).put("heldoutTotal",heldoutTotal);}
 }
 static volatile Model cached;static int loaded=-1;
 static Model read(String raw)throws Exception{JSONObject j=new JSONObject(raw);Model m=new Model(j.getJSONArray("rows"));JSONArray matrix=j.getJSONArray("weights");if(matrix.length()!=m.rows.length())throw new IllegalArgumentException("Pesos incompatibles.");for(int i=0;i<m.weights.length;i++){JSONArray line=matrix.getJSONArray(i);if(line.length()!=D)throw new IllegalArgumentException("Dimensión inválida.");for(int d=0;d<D;d++){float x=(float)line.getDouble(d);if(Float.isNaN(x)||Float.isInfinite(x)||Math.abs(x)>100)throw new IllegalArgumentException("Peso inválido.");m.weights[i][d]=x;}}m.exact=j.getInt("exact");m.heldout=j.getInt("heldout");m.heldoutTotal=j.getInt("heldoutTotal");return m;}
 static synchronized void restore(Context c){int version=prefs(c).getInt("revision",0);if(loaded==version)return;try{String raw=prefs(c).getString("model","");cached=raw.isEmpty()?null:read(raw);loaded=version;}catch(Exception e){cached=null;loaded=version;prefs(c).edit().putString("error","No cargué el recuperador; conservé el chat base.").apply();}}
 static JSONArray data(Context c)throws Exception{return new JSONArray(prefs(c).getString("data","[]"));}
 static boolean question(String text){String q=ChatLanguage.normalize(text);return q.matches("(?s)^(?:que|como|cual|quien|donde|por que|cuanto|cuando) .*")&&!q.matches("(?s).*\\b(?:borra|olvida|aplica|reinstala|actualiza|modifica|java|modulos|reconstruye)\\b.*");}
 static synchronized String teach(Context c,String question,String answer)throws Exception{if(!question(question))throw new IllegalArgumentException("Para aprender una respuesta usá una pregunta informativa. Las órdenes de app y escena conservan su motor.");JSONArray old=data(c),next=new JSONArray();JSONObject item=null;for(int i=0;i<old.length();i++){JSONObject row=old.getJSONObject(i);if(ChatLanguage.normalize(row.getString("question")).equals(ChatLanguage.normalize(question)))item=row;else next.put(row);}if(item==null)item=new JSONObject().put("question",question).put("variants",new JSONArray()).put("source","user");item.put("answer",answer);next.put(item);new Model(next);if(!prefs(c).edit().putString("data",next.toString()).commit())throw new java.io.IOException("No pude guardar la corrección.");return prefs(c).getBoolean("auto",true)?train(c):"Guardé el ejemplo. El autoaprendizaje está pausado; podés decir ‘entrena mis correcciones’.";}
 static synchronized String train(Context c)throws Exception{JSONArray rows=data(c);Model candidate=new Model(rows);Model validation=new Model(rows);validation.train(true);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);JSONArray variants=row.getJSONArray("variants");if(variants.length()>0){String q=variants.getString(variants.length()-1); // Do not use the held-out variant in the lexical gate either.
    JSONArray copy=new JSONArray(rows.toString());copy.getJSONObject(i).getJSONArray("variants").remove(variants.length()-1);Model check=new Model(copy);check.weights=validation.weights;candidate.heldoutTotal++;if(check.select(q,false)==i)candidate.heldout++;}}
  candidate.train(false);for(int i=0;i<rows.length();i++)if(candidate.select(rows.getJSONObject(i).getString("question"),true)==i)candidate.exact++;if(candidate.exact!=rows.length())throw new IllegalArgumentException("La actualización perdió un ejemplo anterior.");Model previous=cached;if(previous!=null&&previous.heldoutTotal==candidate.heldoutTotal&&candidate.heldout<previous.heldout)throw new IllegalArgumentException("La evaluación de variantes empeoró; conservé el modelo anterior.");String raw=candidate.json().toString();JSONArray history=new JSONArray(prefs(c).getString("history","[]")),next=new JSONArray();for(int i=Math.max(0,history.length()-2);i<history.length();i++)next.put(history.get(i));next.put(prefs(c).getString("model",""));int rev=prefs(c).getInt("revision",0)+1;if(!prefs(c).edit().putString("model",raw).putString("history",next.toString()).putInt("revision",rev).remove("error").commit())throw new java.io.IOException("No pude activar el recuperador.");cached=candidate;loaded=rev;return "Entrené el recuperador propio en este dispositivo · revisión "+rev+".\nRecuperación exacta: "+candidate.exact+"/"+rows.length()+"; variantes apartadas: "+candidate.heldout+"/"+candidate.heldoutTotal+".\nSon pruebas locales, no una medida de inteligencia general. No cambié los pesos del generador de chat. Tus aportes siguen identificados como información del usuario.";}
 static String reply(Context c,String input)throws Exception{if(!question(input))return null;restore(c);Model m=cached;if(m==null)return null;int label=m.select(input,true);if(label<0)return null;prefs(c).edit().putInt("uses",prefs(c).getInt("uses",0)+1).apply();return "Según tu corrección guardada:\n"+m.rows.getJSONObject(label).getString("answer")+"\n[Fuente: aporte del usuario; no verificado con fuentes externas.]";}
 static BananaEngine.Result handle(Context c,String message)throws Exception{String q=ChatLanguage.normalize(message);try{Matcher m=Pattern.compile("(?isu)^aprende esta respuesta:\\s*("+JavaTextPlan.LIT+")\\s*=>\\s*("+JavaTextPlan.LIT+")\\s*$").matcher(message.trim());if(m.matches())return MobileCore.say(c,teach(c,JavaTextPlan.decode(m.group(1)),JavaTextPlan.decode(m.group(2))),"aprendizaje_local");if(q.startsWith("anota esta correccion ")){int at=message.indexOf(':');String correction=at>=0?message.substring(at+1).trim():message.substring("anota esta correccion ".length()).trim();String previous=MobileCore.prefs(c).getString("lastMessage","");if(question(previous))return MobileCore.say(c,teach(c,previous,correction),"aprendizaje_local");return null;}
  Matcher variant=Pattern.compile("(?isu)^aprende esta variante:\\s*("+JavaTextPlan.LIT+")\\s*para\\s*("+JavaTextPlan.LIT+")\\s*$").matcher(message.trim());if(variant.matches()){String newQuestion=JavaTextPlan.decode(variant.group(1)),original=JavaTextPlan.decode(variant.group(2));if(!question(newQuestion))throw new IllegalArgumentException("La variante debe ser una pregunta informativa.");JSONArray rows=data(c);JSONObject found=null;for(int i=0;i<rows.length();i++)if(ChatLanguage.normalize(rows.getJSONObject(i).getString("question")).equals(ChatLanguage.normalize(original)))found=rows.getJSONObject(i);if(found==null)throw new IllegalArgumentException("Primero enseñá la respuesta de la pregunta original.");JSONArray variants=found.getJSONArray("variants");if(variants.length()>=4)throw new IllegalArgumentException("Hasta cuatro variantes por pregunta.");variants.put(newQuestion);new Model(rows);if(!prefs(c).edit().putString("data",rows.toString()).commit())throw new java.io.IOException("No pude guardar la variante.");return MobileCore.say(c,prefs(c).getBoolean("auto",true)?train(c):"Variante guardada; entrenamiento pausado.","aprendizaje_local");}
  if(q.equals("entrena mis correcciones"))return MobileCore.say(c,train(c),"aprendizaje_local");if(q.matches("pausa autoaprendizaje|activa autoaprendizaje")){if(!prefs(c).edit().putBoolean("auto",q.startsWith("activa")).commit())throw new java.io.IOException("No pude guardar la opción de aprendizaje.");return MobileCore.say(c,q.startsWith("activa")?"Activé el entrenamiento al recibir correcciones tuyas.":"Pausé el entrenamiento automático. Lo aprendido se conserva.","aprendizaje_local");}
  if(q.equals("deshace ultimo aprendizaje")){JSONArray h=new JSONArray(prefs(c).getString("history","[]"));if(h.length()==0)return MobileCore.say(c,"No hay una versión anterior del aprendizaje.","aprendizaje_local");String raw=h.getString(h.length()-1);Model restored=raw.isEmpty()?null:read(raw);JSONArray remaining=new JSONArray();for(int i=0;i<h.length()-1;i++)remaining.put(h.get(i));int revision=prefs(c).getInt("revision",0)+1;if(!prefs(c).edit().putString("model",raw).putString("data",restored==null?"[]":restored.rows.toString()).putString("history",remaining.toString()).putInt("revision",revision).commit())throw new java.io.IOException("No pude recuperar el aprendizaje.");cached=restored;loaded=revision;return MobileCore.say(c,"Recuperé el recuperador y los ejemplos anteriores.","aprendizaje_local");}
  if(q.matches("estado del aprendizaje|que aprendiste")){restore(c);Model model=cached;return MobileCore.say(c,"Aprendizaje local · revisión "+prefs(c).getInt("revision",0)+"\nAutoaprendizaje: "+prefs(c).getBoolean("auto",true)+"\nEjemplos guardados: "+data(c).length()+"; activos: "+(model==null?0:model.rows.length())+"\nPesos del recuperador: "+(model==null?0:model.rows.length()*D)+"\nVariantes apartadas: "+(model==null?"0/0":model.heldout+"/"+model.heldoutTotal)+"\nRespuestas recuperadas: "+prefs(c).getInt("uses",0)+"\nNo aprende tomando sus propias respuestas como verdades ni reentrena el generador de chat.\n"+prefs(c).getString("error",""),"aprendizaje_local");}
  if(q.equals("reinicia aprendizaje local")||q.equals("borra mis correcciones")){if(!prefs(c).edit().clear().commit())throw new java.io.IOException("No pude borrar el aprendizaje.");MobileCore.prefs(c).edit().remove("feedback").commit();cached=null;loaded=0;return MobileCore.say(c,"Borré ejemplos, pesos y copias del aprendizaje local; conservé las escenas.","aprendizaje_local");}
 }catch(Exception e){return MobileCore.say(c,"No activé un aprendizaje nuevo: "+e.getMessage(),"aprendizaje_local");}return null;}
}
